sp_widget.client_script:
api.controller = function () {
    var c = this;

    c.refresh = function () {
        c.server.update().then(function (response) {
            c.data.songs = response.data.songs;
        });
    };

    c.getStatusClass = function (status) {
        var statusMap = {
            'draft': 'label-default',
            'pending': 'label-warning',
            'approved': 'label-info',
            'published': 'label-success',
            'rejected': 'label-danger',
            'archived': 'label-default'
        };
        return statusMap[status] || 'label-default';
    };
};

sp_widget.css:
.song-list-container {
  padding: 20px 0;
}

.page-title {
  margin-top: 0;
  font-weight: 300;
  color: #333;
}

.song-list-container .table {
  margin-top: 15px;
}

.song-list-container .table th {
  background-color: #f5f5f5;
  font-weight: 600;
  text-transform: uppercase;
  font-size: 12px;
  letter-spacing: 0.5px;
  color: #555;
}

.song-list-container .table td {
  vertical-align: middle;
}

.song-list-container .label {
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 3px;
  font-weight: 500;
}

sp_widget.script:
(function () {
    data.songs = [];
    var gr = new GlideRecord('x_2015479_wa_str_0_song');
    gr.addActiveQuery();
    gr.orderByDesc('sys_created_on');
    gr.setLimit(100);
    gr.query();
    while (gr.next()) {
        data.songs.push({
            sys_id: gr.getUniqueValue(),
            song_title: gr.getValue('song_title'),
            primary_artist: gr.getDisplayValue('primary_artist'),
            genre: gr.getValue('genre'),
            song_status: gr.getValue('song_status'),
            song_status_display: gr.getDisplayValue('song_status'),
            isrc: gr.getValue('isrc')
        });
    }
})();
